solution:
import { useState } from 'react';

export function useSetState(initial = []) {
  const [set, setSet] = useState(() => new Set(initial));
  return {
    set,
    add: (item) => setSet(s => new Set([...s, item])),
    remove: (item) => setSet(s => { const n = new Set(s); n.delete(item); return n; }),
    has: (item) => set.has(item),
    toggle: (item) => setSet(s => { const n = new Set(s); n.has(item) ? n.delete(item) : n.add(item); return n; }),
    clear: () => setSet(new Set()),
  };
}
